1: # 门户H5 本地部署 —— nginx 站点 (root 指向 D:/repository/门户H5/dist)
2: # 独立站点，与「门户」(8092) 互不干扰。
3: # API 代理复用 门户 的 v2 dev 网关（与 门户.conf 一致）。
4: # 代理对齐 env VITE_APP_PROXY_ADDRESS（v2 网关）
5: 
6: server {
7:     listen 8091;
8:     server_name localhost;
9:     root D:/repository/门户H5/dist;
10:     index index.html;
11:     charset utf-8;
12:     client_max_body_size 100m;
13: 
14:     # ---- 弱网优化：文本资源压缩（放在 server 内，避免与门户.conf 的 http 级 gzip 重复）----
15:     # 只压缩文本类资源（图片/字体已是二进制，压缩反而浪费 CPU）。
16:     gzip on;
17:     gzip_comp_level 5;
18:     gzip_min_length 1024;
19:     gzip_vary on;
20:     gzip_proxied any;
21:     gzip_http_version 1.1;
22:     gzip_types
23:         text/plain
24:         text/css
25:         text/xml
26:         text/javascript
27:         application/javascript
28:         application/json
29:         application/manifest+json
30:         application/xml
31:         application/rss+xml
32:         application/atom+xml
33:         image/svg+xml
34:         font/ttf
35:         font/otf;
36: 
37:     # 代理公共配置（以下所有 proxy_pass location 继承）
38:     proxy_http_version 1.1;
39:     proxy_set_header Connection "";
40:     proxy_set_header Host 127.0.0.1:8086;
41:     proxy_set_header X-Real-IP $remote_addr;
42:     proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
43:     proxy_set_header X-Forwarded-Proto $scheme;
44:     proxy_connect_timeout 60s;
45:     proxy_send_timeout 120s;
46:     proxy_read_timeout 120s;
47: 
48:     # 静态资源缓存（文件名带内容 hash，可长缓存）
49:     location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|xlsx|json)$ {
50:         add_header Cache-Control "public, max-age=2592000, immutable" always;
51:         access_log off;
52:         try_files $uri =404;
53:     }
54:     location = /index.html {
55:         expires -1;
56:         add_header Cache-Control "no-cache, no-store, must-revalidate";
57:         add_header Pragma "no-cache";
58:     }
59:     # 站点版本号（前端发版检测用）：不缓存
60:     location = /version.json {
61:         add_header Cache-Control "no-cache, no-store, must-revalidate";
62:     }
63: 
64:     # 业务 API（v2 dev 网关：保留 /api/v2.0、/api/v3.0 前缀）
65:     location /api/v2.0/ {
66:         # 网关路由本身不含 /api 前缀（生产由入口层剥离），本地代理时此处补剥 /api
67:         proxy_pass http://127.0.0.1:8086/v2.0/;
68:     }
69:     location /api/v3.0/ {
70:         # 网关路由本身不含 /api 前缀（生产由入口层剥离），本地代理时此处补剥 /api
71:         proxy_pass http://127.0.0.1:8086/v3.0/;
72:     }
73:     # 附件/静态代理（对齐 vite /zhi2* proxy）
74:     location ^~ /zhi2/ {
75:         proxy_pass http://127.0.0.1:8086;
76:     }
77:     location ^~ /zhi2-dev/ {
78:         proxy_pass http://127.0.0.1:8086;
79:     }
80:     location ^~ /zhi2-test/ {
81:         proxy_pass http://127.0.0.1:8086;
82:     }
83: 
84:     location / {
85:         try_files $uri $uri/ /index.html;
86:     }
87: }

