$rel = "/zhi2-dev/2026/u/1/g/4f543163-d98b-409e-af53-9d7d3578117c.jpg"
$u = "http://127.0.0.1:9222$rel"
try {
  $r = Invoke-WebRequest -Uri $u -Method GET -UseBasicParsing -TimeoutSec 10
  Write-Output ("STATUS " + $r.StatusCode)
  Write-Output ($r.Content.Substring(0,[Math]::Min(600,$r.Content.Length)))
} catch {
  $e = $_.Exception.Response
  Write-Output ("STATUS " + $e.StatusCode.value__)
  try { $body = (New-Object System.IO.StreamReader($e.GetResponseStream())).ReadToEnd(); Write-Output $body.Substring(0,[Math]::Min(600,$body.Length)) } catch { Write-Output ("body read err " + $_.Exception.Message) }
}

